const cuisinesData = [{"id":"c1","name":"Butter Chicken","region":"north","state":"Delhi / Punjab","description":"Tender chicken cooked in a smooth, rich, aromatic tomato and butter gravy, sweetened with a touch of cream.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3c/Chicken_makhani.jpg/800px-Chicken_makhani.jpg"},{"id":"c2","name":"Chole Bhature","region":"north","state":"Punjab","description":"A classic North Indian dish featuring spicy chickpea curry (chole) paired with puffed, deep-fried leavened flatbreads (bhature).","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Chole_Bhature.jpg/800px-Chole_Bhature.jpg"},{"id":"c3","name":"Rogan Josh","region":"north","state":"Jammu & Kashmir","description":"An aromatic slow-cooked lamb curry from Kashmir, infused with ginger, garlic, fennel seeds, and local Kashmiri red chilies.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/Rogan_Josh.jpg/800px-Rogan_Josh.jpg"},{"id":"c4","name":"Masala Dosa","region":"south","state":"Karnataka","description":"Thin, crispy fermented rice and lentil crepe rolled with a spiced potato mash inside, served with hot sambar and fresh coconut chutney.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Dosa_and_ghee.jpg/800px-Dosa_and_ghee.jpg"},{"id":"c5","name":"Hyderabadi Biryani","region":"south","state":"Telangana","description":"An iconic dish made of aromatic Basmati rice, marinated spices, and meat, cooked in layers in a sealed pot over slow fire (Dum style).","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5ce/Hyderabadi_Biryani.jpg/800px-Hyderabadi_Biryani.jpg"},{"id":"c6","name":"Idli Sambar","region":"south","state":"Tamil Nadu","description":"Soft, fluffy steamed rice cakes served with a rich, tangy lentil stew loaded with vegetables and fresh spices.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2b/Idli_Sambar.jpg/800px-Idli_Sambar.jpg"},{"id":"c7","name":"Litti Chokha","region":"east","state":"Bihar","description":"Healthy whole-wheat dough balls stuffed with roasted chickpea flour (sattu) and spices, roasted over dung/coal, and served with a mash of eggplant and potatoes.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/Litti_Chokha_served_in_a_plate.jpg/800px-Litti_Chokha_served_in_a_plate.jpg"},{"id":"c8","name":"Machher Jhol","region":"east","state":"West Bengal","description":"A simple, traditional spicy fish stew prepared with mustard oil, turmeric, ginger, and local five-spice blend (Panch Phoron).","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/14/Machher_Jhol_-_Traditional_Bengali_Fish_Curry.jpg/800px-Machher_Jhol_-_Traditional_Bengali_Fish_Curry.jpg"},{"id":"c9","name":"Rasgulla","region":"east","state":"West Bengal / Odisha","description":"Soft, spongy balls of chhena (cottage cheese) cooked in a light, sweet sugar syrup until juicy and airy.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7b/Rasgulla_-_A_sweet_dish.jpg/800px-Rasgulla_-_A_sweet_dish.jpg"},{"id":"c10","name":"Dhokla","region":"west","state":"Gujarat","description":"A light, spongy steamed snack made from fermented chickpea flour batter, tempered with mustard seeds, sesame, and green chilies.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d7/Dhokla-a_Gujarati_Snack.jpg/800px-Dhokla-a_Gujarati_Snack.jpg"},{"id":"c11","name":"Vada Pav","region":"west","state":"Maharashtra","description":"Mumbai's ultimate street food: a deep-fried spiced potato fritter (vada) inside a sliced soft bun (pav), smeared with hot garlic chutney.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Vada_Pav.jpg/800px-Vada_Pav.jpg"},{"id":"c12","name":"Bebinca","region":"west","state":"Goa","description":"A rich, classic Goan dessert consisting of multiple layers made of eggs, coconut milk, sugar, flour, and aromatic ghee.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Bebinca.jpg/800px-Bebinca.jpg"},{"id":"c13","name":"Momos","region":"northeast","state":"Sikkim","description":"Bite-sized steamed dumplings stuffed with seasoned vegetables or meats, accompanied by a fiery red chili dipping sauce.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/86/Momos_with_sauce.jpg/800px-Momos_with_sauce.jpg"},{"id":"c14","name":"Smoked Pork with Bamboo","region":"northeast","state":"Nagaland","description":"Smoked pork pieces cooked with bamboo shoots, fermented soybean, and hot Naga king chilies, making a highly aromatic local specialty.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/21/Pork_curry_with_bamboo_shoot.jpg/800px-Pork_curry_with_bamboo_shoot.jpg"},{"id":"c15","name":"Jadoh","region":"northeast","state":"Meghalaya","description":"A Khasi tribal rice dish cooked with red hill rice, ginger, black pepper, and herbs, often mixed with pork or chicken broth.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e5/Jadoh.jpg/800px-Jadoh.jpg"},{"id":"c16","name":"Dal Baati Churma","region":"north","state":"Rajasthan","description":"Baked wheat rolls (baati) crushed and soaked in ghee, served with spicy lentils (dal) and a sweet crumbled wheat dessert (churma).","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/23/Dal_Bati_Churma.jpg/800px-Dal_Bati_Churma.jpg"},{"id":"c17","name":"Tunday Kabab","region":"north","state":"Uttar Pradesh","description":"Melt-in-the-mouth minced meat kababs from Lucknow, slow-cooked with over a dozen secret spices on a small skillet.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Tunday_Kabab.jpg/800px-Tunday_Kabab.jpg"},{"id":"c18","name":"Poha Jalebi","region":"north","state":"Madhya Pradesh","description":"A popular Indore breakfast pairing of spiced flattened rice (poha) with crunchy, syrup-soaked jalebi for a sweet-savory start to the day.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Indori_Poha.jpg/800px-Indori_Poha.jpg"},{"id":"c19","name":"Bajra Khichdi","region":"north","state":"Haryana","description":"A wholesome one-pot meal of pearl millet and lentils, slow-cooked with ghee, popular in the rural farmlands of Haryana.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Bajra_Khichdi.jpg/800px-Bajra_Khichdi.jpg"},{"id":"c20","name":"Siddu","region":"north","state":"Himachal Pradesh","description":"A steamed wheat bread stuffed with a sweet or savory poppy-seed and walnut filling, a winter staple of the Himachal hills.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a1/Siddu_with_ghee.jpg/800px-Siddu_with_ghee.jpg"},{"id":"c21","name":"Kerala Sadya","region":"south","state":"Kerala","description":"A grand vegetarian feast served on a banana leaf, featuring rice with a variety of curries, pickles, and payasam (sweet pudding).","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/ca/Kerala_Sadya.jpg/800px-Kerala_Sadya.jpg"},{"id":"c22","name":"Andhra Chicken Curry","region":"south","state":"Andhra Pradesh","description":"A fiery, tangy chicken curry loaded with red chilies and tamarind, showcasing the bold, spice-forward flavors of Andhra cooking.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Spicy_Chicken_Curry.jpg/800px-Spicy_Chicken_Curry.jpg"},{"id":"c23","name":"Pakhala Bhata","region":"east","state":"Odisha","description":"Fermented rice soaked in water overnight, served cold with fried vegetables and yogurt — a refreshing summer staple of Odisha.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6d/Pakhala_Thali.jpg/800px-Pakhala_Thali.jpg"},{"id":"c24","name":"Dhuska","region":"east","state":"Jharkhand","description":"Deep-fried rice and lentil pancakes, crispy outside and soft inside, usually served with spicy chickpea curry or curd.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/67/Dhuska_jharkhand.jpg/800px-Dhuska_jharkhand.jpg"},{"id":"c25","name":"Assamese Khar","region":"northeast","state":"Assam","description":"A one-of-a-kind alkaline dish made by filtering water through sun-dried banana peel ash, cooked with raw papaya and lentils.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3f/Assamese_Thali.jpg/800px-Assamese_Thali.jpg"}];
const festivalsData = [{"name":"Diwali","subtitle":"The Festival of Lights","description":"Diwali celebrates the victory of light over darkness and good over evil. Homes are decorated with clay lamps (diyas), intricate sand drawings (rangoli), and fireworks illuminate the night sky across India.","image":"https://images.unsplash.com/photo-1572007010476-80f4f9f7ba37?auto=format&fit=crop&w=800","story":"According to ancient epics, Diwali marks the day Lord Rama, along with Sita and Lakshmana, returned to their kingdom of Ayodhya after 14 years of exile and defeating the demon king Ravana. The citizens of Ayodhya illuminated the entire city with clay oil lamps (diyas) to guide them home in the dark moonless night. Spirited celebrations also honor Goddess Lakshmi, the deity of wealth and prosperity, welcoming her blessings into clean, illuminated households."},{"name":"Holi","subtitle":"The Festival of Colors","description":"Holi marks the arrival of spring and victory of devotion. People of all backgrounds gather in the streets to throw vibrant dry colors (gulal) and splash colored water on each other, singing and sharing sweets.","image":"https://images.unsplash.com/photo-1551805723-888e6a10de4b?auto=format&fit=crop&w=800","story":"Holi's origins lie in the legendary tale of young prince Prahlada, an ardent devotee of Lord Vishnu. Despite his demonic father King Hiranyakashipu's attempts to kill him, Prahlada survived a blazing fire unscathed due to his unwavering faith, while the king's sister Holika perished in the pyre (commemorated as 'Holika Dahan'). The next day, people celebrate the triumph of good over evil by splashing colors, symbolizing the colorful arrival of spring."},{"name":"Eid","subtitle":"Festival of Gratitude & Giving","description":"Eid-ul-Fitr marks the completion of the fasting month of Ramadan. Muslims wear new clothes, offer special prayers, exchange gifts, and prepare 'Sheer Khurma' (sweet vermicelli pudding) for family and guests.","image":"https://images.unsplash.com/photo-1563294326-7eeb3467c9c0?auto=format&fit=crop&w=800","story":"Eid-ul-Fitr, meaning the 'Festival of Breaking the Fast', marks the joyous conclusion of Ramadan, the holy month of fasting, prayer, and self-reflection. It is a day of deep spiritual gratitude to Allah for strength and self-control. Muslims celebrate by wearing new clothes, visiting family, sharing a sweet feast of vermicelli pudding (Sheer Khurma), and contributing charity (Zakat-al-Fitr) to ensure the poor can celebrate too."},{"name":"Pongal","subtitle":"The Harvest Celebration","description":"A major harvest festival of South India, especially Tamil Nadu. Spanning four days, it thanks the Sun God and cattle. Traditional sweet rice pudding is boiled in clay pots until it overflows, symbolizing abundance.","image":"https://images.unsplash.com/photo-1610452331575-d143d2c88f4e?auto=format&fit=crop&w=800","story":"Pongal is a four-day thanksgiving festival celebrated in Tamil Nadu, dedicated to thanking Surya (the Sun God) and cattle for a bountiful harvest. On the main day, freshly harvested rice is boiled with milk and jaggery in a decorated clay pot. As the milk boils over, families shout 'Pongalo Pongal!' (May rice boil over!), symbolizing abundance, and share the sweet pudding with family and domestic animals."},{"name":"Navratri","subtitle":"The Nine Nights of Dance","description":"Dedicated to Goddess Durga, this festival is celebrated with intense energy. In Gujarat, people dance 'Garba' and 'Dandiya' all night, while in West Bengal, 'Durga Puja' features massive, beautifully decorated temple setups (pandals).","image":"https://images.unsplash.com/photo-1662993886538-2d2c18d36371?auto=format&fit=crop&w=800","story":"Navratri, meaning 'Nine Nights', honors the supreme feminine energy, Goddess Durga. The celebration commemorates her epic nine-day battle and ultimate triumph over the shape-shifting buffalo demon Mahishasura, who had terrorized the cosmos. Dancers wear gorgeous traditional dresses and perform Garba and Dandiya Raas in circular choreographies, representing the cyclical nature of time and life."},{"name":"Bihu","subtitle":"The Spring Harvest of Assam","description":"Bihu represents a set of three festivals in Assam. Rongali Bihu in April marks the Assamese New Year, celebrated with joyful traditional dances, folk songs using the dhol, and delicious coconut cakes.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/Bihu_dance.jpg/800px-Bihu_dance.jpg","story":"Bihu consists of three distinct agricultural festivals in Assam: Bohag Bihu (in April, celebrating the spring harvest and Assamese New Year), Kongali Bihu (in October, praying for crop protection), and Bhogali Bihu (in January, marking the end of harvest with community feasts). Bohag Bihu is marked by energetic dances using traditional instruments like the dhol (drum) and pepa (horn flute), mirroring the joy of spring."}];
const cultureData = [{"title":"Bharatanatyam","category":"dance","description":"An ancient, highly structured classical dance form originating in Tamil Nadu. It is renowned for its geometric poses, complex rhythmic footwork, and detailed facial expressions storytelling Vedic myths.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Bharatanatyam_Dance.jpg/800px-Bharatanatyam_Dance.jpg"},{"title":"Kathakali","category":"dance","description":"A spectacular dance-drama from Kerala. Actors undergo intense training to master complex facial movements, performing in heavy, vibrant makeup and multi-layered dress to depict epic battle stories.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Kathakali_Performance.jpg/800px-Kathakali_Performance.jpg"},{"title":"Sitar","category":"music","description":"A classical stringed instrument popular in Hindustani music. It has a long neck, deep gourd resonator, and sympathetic strings that produce a rich, resonant tone, popularized globally by Pt. Ravi Shankar.","image":"https://images.unsplash.com/photo-1596758410222-38d011853ba5?auto=format&fit=crop&w=800"},{"title":"Traditional Attires","category":"clothing","description":"Indian clothing is incredibly diverse, from the elegant, unstitched six-yard drapes of silk Saris worn by women, to the royal structured Sherwani jackets and casual Dhoti-Kurtas worn by men.","image":"https://images.unsplash.com/photo-1583391733958-d25e77b22a28?auto=format&fit=crop&w=800"},{"title":"Bhangra","category":"dance","description":"A highly energetic, celebratory folk dance from Punjab. Danced to the fast, driving rhythm of the double-headed Dhol drum, it was originally performed during the spring harvest festival Baisakhi.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Bhangra_Dance.jpg/800px-Bhangra_Dance.jpg"},{"title":"Tabla","category":"music","description":"The primary percussion instrument of North Indian music. It consists of a pair of small drums played with hands and fingers, capable of a vast range of acoustic tones and lightning-fast tempos.","image":"https://images.unsplash.com/photo-1635398240578-8baea8df570b?auto=format&fit=crop&w=800"}];
