const quizQuestions = [{"question":"Which state is famous for the dish 'Litti Chokha'?","options":["Bihar","Uttar Pradesh","Rajasthan","Madhya Pradesh"],"answer":"Bihar"},{"question":"Where does the delicious layered dessert 'Bebinca' originate from?","options":["Goa","Kerala","West Bengal","Maharashtra"],"answer":"Goa"},{"question":"Which state is known for the tangy fish stew 'Masor Tenga'?","options":["Assam","West Bengal","Odisha","Nagaland"],"answer":"Assam"},{"question":"The spicy potato burger 'Vada Pav' is the ultimate street food of which state?","options":["Maharashtra","Gujarat","Karnataka","Punjab"],"answer":"Maharashtra"},{"question":"Which state serves 'Dham' (a traditional festive feast cooked by temple chefs)?","options":["Himachal Pradesh","Uttarakhand","Jammu & Kashmir","Sikkim"],"answer":"Himachal Pradesh"},{"question":"Which state is the origin of the sweet 'Mysore Pak'?","options":["Karnataka","Tamil Nadu","Andhra Pradesh","Kerala"],"answer":"Karnataka"},{"question":"Which state is famous for the steamed savory cake 'Dhokla'?","options":["Gujarat","Rajasthan","Madhya Pradesh","Haryana"],"answer":"Gujarat"},{"question":"The sour-leaf chutney 'Gongura Pachadi' is a staple in which state?","options":["Andhra Pradesh","Telangana","Tamil Nadu","Karnataka"],"answer":"Andhra Pradesh"}];